  app.onError((e, c) => {
    if (e instanceof HTTPException && e.cause instanceof Error) {
      return c.json({ name: e.cause.name, message: e.cause.message }, 401)
    }
    return c.text(e.message, 401)
  })

  it('Should not authorize', async () => {
