describe('jwtRefresh middleware', () => {
  const secret = 'a-secret'
  const refreshSecret = 'a-refresh-secret'

  const signAccess = (exp: number, extra: Record<string, unknown> = {}) =>
    sign({ sub: 'user-1', exp, ...extra }, secret, 'HS256')
  const signRefresh = (exp: number, key: string = refreshSecret) =>
    sign({ sub: 'user-1', type: 'refresh', exp }, key, 'HS256')

  const future = () => Math.floor(Date.now() / 1000) + 3600
  const past = () => Math.floor(Date.now() / 1000) - 3600

  it('Should throw when secret is missing', () => {
    expect(() =>
      // @ts-expect-error - intentionally testing without secret
      jwtRefresh({ alg: 'HS256', onRefresh: async () => '' })
    ).toThrow('JWT refresh middleware requires options for "secret"')
  })

  it('Should throw when alg is missing', () => {
    expect(() =>
      // @ts-expect-error - intentionally testing without alg
      jwtRefresh({ secret, onRefresh: async () => '' })
    ).toThrow('JWT refresh middleware requires options for "alg"')
  })

  it('Should throw when onRefresh is missing', () => {
    expect(() =>
      // @ts-expect-error - intentionally testing without onRefresh
      jwtRefresh({ secret, alg: 'HS256' })
    ).toThrow('JWT refresh middleware requires options for "onRefresh"')
  })

  it('Should authorize with a valid access token and not invoke onRefresh', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'should-not-be-called')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const accessToken = await signAccess(future())
    const req = new Request('http://localhost/auth/me')
    req.headers.set('Authorization', `Bearer ${accessToken}`)
    const res = await app.request(req)

    expect(res.status).toBe(200)
    expect(onRefresh).not.toHaveBeenCalled()
    expect(res.headers.get('X-Access-Token')).toBeNull()
    const body = await res.json()
    expect(body.sub).toBe('user-1')
  })

  it('Should refresh access token when expired and refresh cookie is valid', async () => {
    const app = new Hono()
    const newAccessToken = await signAccess(future(), { refreshed: true })
    const onRefresh = vi.fn(async (_payload: unknown) => newAccessToken)
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const validRefresh = await signRefresh(future())

    const req = new Request('http://localhost/auth/me', {
      headers: {
        Authorization: `Bearer ${expiredAccess}`,
        Cookie: `refresh_token=${validRefresh}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(200)
    expect(onRefresh).toHaveBeenCalledTimes(1)
    const calledWith = onRefresh.mock.calls[0][0] as { type?: string; sub?: string }
    expect(calledWith.type).toBe('refresh')
    expect(calledWith.sub).toBe('user-1')
    expect(res.headers.get('X-Access-Token')).toBe(newAccessToken)
    const body = await res.json()
    expect(body.refreshed).toBe(true)
  })

  it('Should respond 401 when access token is expired and no refresh cookie', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'unused')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const req = new Request('http://localhost/auth/me')
    req.headers.set('Authorization', `Bearer ${expiredAccess}`)
    const res = await app.request(req)

    expect(res.status).toBe(401)
    expect(onRefresh).not.toHaveBeenCalled()
  })

  it('Should respond 401 when both access and refresh tokens are invalid', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'unused')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const expiredRefresh = await signRefresh(past())

    const req = new Request('http://localhost/auth/me', {
      headers: {
        Authorization: `Bearer ${expiredAccess}`,
        Cookie: `refresh_token=${expiredRefresh}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(401)
    expect(onRefresh).not.toHaveBeenCalled()
  })

  it('Should respond 401 when no tokens are provided', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'unused')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const res = await app.request('http://localhost/auth/me')
    expect(res.status).toBe(401)
    expect(onRefresh).not.toHaveBeenCalled()
  })

  it('Should default refreshSecret to secret when omitted', async () => {
    const app = new Hono()
    const newAccessToken = await signAccess(future(), { refreshed: true })
    const onRefresh = vi.fn(async () => newAccessToken)
    app.use('/auth/*', jwtRefresh({ secret, alg: 'HS256', onRefresh }))
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

