  it('Should respond 401 when no tokens are provided', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'unused')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const res = await app.request('http://localhost/auth/me')
    expect(res.status).toBe(401)
    expect(onRefresh).not.toHaveBeenCalled()
  })

  it('Should default refreshSecret to secret when omitted', async () => {
    const app = new Hono()
    const newAccessToken = await signAccess(future(), { refreshed: true })
    const onRefresh = vi.fn(async () => newAccessToken)
    app.use('/auth/*', jwtRefresh({ secret, alg: 'HS256', onRefresh }))
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const refreshSignedWithSecret = await signRefresh(future(), secret)

    const req = new Request('http://localhost/auth/me', {
      headers: {
        Authorization: `Bearer ${expiredAccess}`,
        Cookie: `refresh_token=${refreshSignedWithSecret}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(200)
    expect(onRefresh).toHaveBeenCalledTimes(1)
    expect(res.headers.get('X-Access-Token')).toBe(newAccessToken)
  })

  it('Should support a custom refreshCookie name', async () => {
    const app = new Hono()
    const newAccessToken = await signAccess(future())
    const onRefresh = vi.fn(async () => newAccessToken)
    app.use(
      '/auth/*',
      jwtRefresh({
        secret,
        alg: 'HS256',
        refreshSecret,
        refreshCookie: 'rt',
        onRefresh,
      })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const validRefresh = await signRefresh(future())

    const req = new Request('http://localhost/auth/me', {
      headers: {
        Authorization: `Bearer ${expiredAccess}`,
        Cookie: `rt=${validRefresh}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(200)
    expect(onRefresh).toHaveBeenCalledTimes(1)
    expect(res.headers.get('X-Access-Token')).toBe(newAccessToken)
  })

  it('Should 401 when onRefresh returns an unverifiable token', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'not-a-jwt')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const expiredAccess = await signAccess(past())
    const validRefresh = await signRefresh(future())

    const req = new Request('http://localhost/auth/me', {
      headers: {
        Authorization: `Bearer ${expiredAccess}`,
        Cookie: `refresh_token=${validRefresh}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(401)
    expect(onRefresh).toHaveBeenCalledTimes(1)
  })

  it('Should 401 with invalid credentials structure when Authorization is malformed', async () => {
    const app = new Hono()
    const onRefresh = vi.fn(async () => 'unused')
    app.use(
      '/auth/*',
      jwtRefresh({ secret, alg: 'HS256', refreshSecret, onRefresh })
    )
    app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

    const validRefresh = await signRefresh(future())
    const url = 'http://localhost/auth/me'
    const req = new Request(url, {
      headers: {
        Authorization: 'NotBearer abc',
        Cookie: `refresh_token=${validRefresh}`,
      },
    })
    const res = await app.request(req)

    expect(res.status).toBe(401)
    expect(res.headers.get('www-authenticate')).toEqual(
      `Bearer realm="${url}",error="invalid_request",error_description="invalid credentials structure"`
    )
    expect(onRefresh).not.toHaveBeenCalled()
  })
})

